<?php /** @var array<string,mixed> $r */ /** @var list<array<string,mixed>> $history */ /** @var list<array<string,mixed>> $notes */ /** @var bool $canManage */ /** @var bool $canDecide */ /** @var list<string> $next */
/** @var list<array<string,mixed>> $emailLog */ /** @var list<int> $mailable */ /** @var list<array<string,mixed>> $commissions */ /** @var list<array<string,mixed>> $claims */ use Vertex\Core\View;
$url = '/referrals/' . $r['public_id']; $v = static fn (string $k): string => old($k); $working = in_array($r['status'], ['approved', 'contacted', 'qualified', 'quote_sent'], true); ?>
<div class="page-head"><div><p class="eyebrow">Referral</p><h1><?= e($r['reference']) ?></h1></div><a class="btn btn-ghost" href="/referrals">&larr; Referrals</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><?= View::partial('pbadge', ['kind' => 'referral', 's' => $r['status']]) ?></div>
    <div><span class="muted">Credit</span><br><?= e(config("referrals.attribution_labels.{$r['attribution']}", $r['attribution'])) ?><?= $r['attribution_locked'] ? ' 🔒 locked' : '' ?></div>
    <div><span class="muted">Partner</span><br><a href="/referrals/partners/<?= e($r['partner_public_id']) ?>"><?= e($r['partner_name']) ?></a></div><div><span class="muted">Submitted</span><br><?= e(local_time($r['created_at'])) ?></div></div>
    <dl class="detail-list"><dt>Prospect</dt><dd><?= e($r['prospect_name']) ?></dd><?php if ($r['business_name']) : ?><dt>Business</dt><dd><?= e($r['business_name']) ?></dd><?php endif; ?>
        <dt>Contact</dt><dd><?= e(trim(($r['email'] ?? '') . ' ' . ($r['phone'] ?? ''))) ?></dd><dt>Service</dt><dd><?= e(config("workflow.services.{$r['service']}", $r['service'])) ?></dd>
        <dt>Description</dt><dd class="prewrap"><?= e($r['description']) ?></dd><?php if ($r['estimated_budget_minor'] !== null) : ?><dt>Estimated budget</dt><dd><?= e(money($r['estimated_budget_minor'])) ?></dd><?php endif; ?>
        <?php if ($r['notes']) : ?><dt>Partner's notes</dt><dd class="prewrap"><?= e($r['notes']) ?></dd><?php endif; ?>
        <?php if ($r['status_reason']) : ?><dt>Reason given</dt><dd class="prewrap"><?= e($r['status_reason']) ?></dd><?php endif; ?>
        <?php if ($r['attribution_reason']) : ?><dt>Credit decision</dt><dd class="prewrap"><?= e($r['attribution_reason']) ?><?= $r['attribution_by_name'] ? '<br><span class="muted">' . e($r['attribution_by_name']) . ' · ' . e(local_time($r['attribution_at'])) . '</span>' : '' ?></dd><?php endif; ?>
        <?php if ($r['duplicate_of_reference']) : ?><dt>Duplicate of</dt><dd><?= e($r['duplicate_of_reference']) ?></dd><?php endif; ?>
        <?php if ($r['enquiry_public_id']) : ?><dt>CRM enquiry</dt><dd><a href="/enquiries/<?= e($r['enquiry_public_id']) ?>"><?= e($r['enquiry_reference']) ?></a></dd><?php endif; ?>
        <?php if ($r['client_public_id']) : ?><dt>Client</dt><dd><a href="/clients/<?= e($r['client_public_id']) ?>"><?= e($r['client_name']) ?></a></dd><?php endif; ?>
        <?php if ($r['project_public_id']) : ?><dt>Project</dt><dd><a href="/projects/<?= e($r['project_public_id']) ?>"><?= e($r['project_code']) ?> · <?= e($r['project_title']) ?></a></dd><?php endif; ?></dl></div>
<?php if ($claims !== []) : ?><div class="panel"><h2>Other claims on the same contact <span class="badge badge-pending">review</span></h2><p class="muted">Matched by email or phone. Nothing is merged automatically.</p>
    <ul class="plain-list"><?php foreach ($claims as $c) : ?><li><a href="/referrals/<?= e($c['public_id']) ?>"><?= e($c['reference']) ?></a> · <?= e($c['partner_name']) ?> · <?= View::partial('pbadge', ['kind' => 'referral', 's' => $c['status']]) ?> · <?= e(config("referrals.attribution_labels.{$c['attribution']}", $c['attribution'])) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($canManage && $next !== []) : ?><div class="panel"><h2>Change status</h2>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="status">
        <div class="field"><label for="st">New status</label><select id="st" name="status" required><?php foreach ($next as $s) : ?><option value="<?= e($s) ?>"><?= e(config("referrals.referral_statuses.{$s}", $s)) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="rs">Message to the partner (required for Rejected / Not Converted)</label><textarea id="rs" name="reason" rows="2" maxlength="500"><?= e($v('reason')) ?></textarea></div>
        <div class="field"><label for="in">Internal note (optional, partner cannot see it)</label><textarea id="in" name="internal_note" rows="2" maxlength="3000"><?= e($v('internal_note')) ?></textarea></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Update status</button></div></form></div><?php endif; ?>
<?php if ($canManage && !$r['enquiry_id'] && $working) : ?><div class="panel"><h2>CRM enquiry</h2><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="enquiry"><button class="btn btn-ghost btn-sm" type="submit">Create a CRM enquiry from this referral</button></form><p class="muted">Creates a new enquiry only. It never merges with an existing client or enquiry.</p></div><?php endif; ?>
<?php if ($canManage && !in_array($r['status'], ['converted', 'rejected'], true)) : ?><div class="panel"><h2>Link CRM records</h2>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="link">
        <div class="field"><label for="le">Enquiry reference id (optional)</label><input id="le" name="enquiry" maxlength="32" placeholder="32-character id from the enquiry URL"></div>
        <div class="field"><label for="lp">Project id (optional)</label><input id="lp" name="project" maxlength="32" placeholder="32-character id from the project URL"></div>
        <div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Link</button></div></form></div><?php endif; ?>
<?php if ($canManage && $working) : ?><div class="panel"><h2>Mark converted</h2><p class="muted">A referral is Converted only when it is linked to a real project. Approval or a sent quotation never converts it.</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Mark this referral as converted?"><?= csrf_field() ?><input type="hidden" name="action" value="convert">
        <div class="field"><label for="cp">Project id</label><input id="cp" name="project" required maxlength="32" value="<?= e($r['project_public_id'] ?? '') ?>"></div>
        <div class="form-actions"><button class="btn btn-primary btn-sm" type="submit">Mark converted</button></div></form></div><?php endif; ?>
<?php if ($canDecide) : ?><div class="panel"><h2>Credit (attribution) decision</h2>
    <?php if ($r['attribution_locked']) : ?><p>Locked: commission eligibility has been established, so the credit can no longer be changed here. Use a commission adjustment if the decision was wrong.</p>
    <?php else : ?><form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Record this decision?"><?= csrf_field() ?><input type="hidden" name="action" value="attribution">
        <div class="field"><label for="ad">Decision</label><select id="ad" name="decision" required><option value="credited">Credit this partner</option><option value="denied">Do not credit</option><option value="duplicate">Duplicate of another claim</option></select></div>
        <div class="field"><label for="ar">Reason (required)</label><textarea id="ar" name="reason" rows="3" required minlength="10" maxlength="500"></textarea></div>
        <div class="form-actions"><button class="btn btn-primary btn-sm" type="submit">Record decision</button></div></form><?php endif; ?></div><?php endif; ?>
<?php if ($commissions !== []) : ?><div class="panel"><h2>Commission entries</h2><ul class="plain-list"><?php foreach ($commissions as $c) : ?><li><a href="/commissions/<?= e($c['public_id']) ?>"><?= e($c['reference']) ?></a> · <?= e(config("referrals.milestone_labels.{$c['milestone']}", $c['milestone'])) ?> · <?= e(money($c['amount_minor'])) ?> · <?= View::partial('pbadge', ['kind' => 'commission', 's' => $c['status']]) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="panel"><h2>History</h2><ol class="timeline"><?php foreach ($history as $h) : ?><li><strong><?= e(ucfirst($h['event'])) ?><?= $h['to_value'] ? ': ' . e(config("referrals.referral_statuses.{$h['to_value']}", $h['to_value'])) : '' ?></strong> <span class="muted"><?= e(local_time($h['created_at'])) ?> · <?= e($h['actor_name'] ?? 'system') ?><?= $h['visibility'] === 'internal' ? ' · internal' : '' ?></span><?php if ($h['note']) : ?><p class="prewrap"><?= e($h['note']) ?></p><?php endif; ?>
    <?php if ($canManage && in_array((int) $h['id'], $mailable, true)) : ?><a class="btn btn-ghost btn-sm" href="<?= e($url) ?>/email/<?= (int) $h['id'] ?>">Preview email to partner</a><?php endif; ?></li><?php endforeach; ?></ol></div>
<?php if ($emailLog !== []) : ?><div class="panel"><h2>Emails to the partner</h2><ul class="plain-list"><?php foreach ($emailLog as $m) : ?><li><?= e(local_time($m['created_at'])) ?> · <?= e($m['subject']) ?> · <strong><?= e(['sent' => 'Sent', 'failed' => 'Failed', 'not_configured' => 'Not sent (email not configured)'][$m['result']] ?? $m['result']) ?></strong></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="panel"><h2>Internal notes <span class="badge badge-sensitive">staff only</span></h2>
    <?php foreach ($notes as $n) : ?><div class="note"><p class="prewrap"><?= e($n['body']) ?></p><p class="muted"><?= e($n['author'] ?? '') ?> · <?= e(local_time($n['created_at'])) ?></p></div><?php endforeach; ?><?php if ($notes === []) : ?><p class="muted">No notes.</p><?php endif; ?>
    <?php if ($canManage) : ?><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="note"><div class="field"><label for="nb">Add a note</label><textarea id="nb" name="body" rows="2" required maxlength="3000"></textarea></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Add note</button></div></form><?php endif; ?></div>
